-- Jobs and industries: who a resource helps and in which field (src/lib/taxonomy.ts JOBS, INDUSTRIES).
-- Adds resources.jobs and resources.industries, lets the Curator write them through patch_resources, and
-- backfills the 1222 resources published on 2026-10-25 (labelled by hand from their summaries).
alter table public.resources
  add column if not exists jobs text[] not null default '{}',
  add column if not exists industries text[] not null default '{}';
create index if not exists resources_jobs_idx on public.resources using gin (jobs);
create index if not exists resources_industries_idx on public.resources using gin (industries);

create or replace function public.patch_resources(p_token text, p_rows jsonb)
 returns integer
 language plpgsql
 security definer
 set search_path to ''
as $function$
declare x jsonb; n int := 0;
begin
  perform private.check_token(p_token);
  for x in select * from jsonb_array_elements(p_rows) loop
    update public.resources r set
      status        = coalesce(x->>'status', r.status),
      hidden_reason = case when x ? 'status' then (case when x->>'status' = 'hidden' then x->>'hidden_reason' else null end) else r.hidden_reason end,
      category      = coalesce(x->>'category', r.category),
      tags          = case when x ? 'tags' then array(select jsonb_array_elements_text(x->'tags')) else r.tags end,
      jobs          = case when x ? 'jobs' then array(select jsonb_array_elements_text(x->'jobs')) else r.jobs end,
      industries    = case when x ? 'industries' then array(select jsonb_array_elements_text(x->'industries')) else r.industries end,
      level         = coalesce(x->>'level', r.level),
      quality       = coalesce((x->>'quality')::int, r.quality),
      quality_notes = coalesce(x->>'quality_notes', r.quality_notes),
      summary       = coalesce(x->>'summary', r.summary),
      summary_vi    = coalesce(x->>'summary_vi', r.summary_vi),
      use_cases     = coalesce(x->'use_cases', r.use_cases),
      prompts       = coalesce(x->'prompts', r.prompts),
      showcase      = coalesce(x->'showcase', r.showcase),
      demo          = coalesce(x->'demo', r.demo),
      sources       = case when x ? 'sources' then array(select distinct unnest(r.sources || array(select jsonb_array_elements_text(x->'sources')))) else r.sources end,
      classified_at = case when x ? 'category' then now() else r.classified_at end,
      produced_at   = case when x ? 'showcase' then now() else r.produced_at end,
      demoed_at     = case when x ? 'demo' then now() else r.demoed_at end
    where r.full_name = x->>'full_name';
    if found then n := n + 1; end if;
  end loop;
  return n;
end $function$;

-- backfill: slug -> "job[,job]|industry[,industry]"
update public.resources r
   set jobs = string_to_array(split_part(v.value, '|', 1), ','),
       industries = coalesce(string_to_array(nullif(split_part(v.value, '|', 2), ''), ','), '{}')
